<script setup lang="ts">
import {onMounted,onUnmounted,watch} from 'vue';import {useApp} from './stores/app';import Icon from './components/Icon.vue';import {localDay} from './core/logic';import AppUpdate from './components/AppUpdate.vue';
const app=useApp();const nav=[['/','House','Overview'],['/train','Dumbbell','Training'],['/nutrition','Utensils','Nutrition'],['/progress','ChartNoAxesCombined','Progress'],['/coach','Sparkles','AI Coach']];
let tick:ReturnType<typeof setInterval>;
onMounted(()=>{app.init();tick=setInterval(()=>{app.today=localDay();},30000);});onUnmounted(()=>clearInterval(tick));
watch(()=>app.data.profile, p=>{document.documentElement.dataset.theme=p.theme;document.documentElement.dataset.motion=p.reducedMotion?'reduced':'full';},{deep:true,immediate:true});
</script>
<template><a class="skip-link" href="#main-content">Skip to content</a><div class="app-layout"><aside class="sidebar"><RouterLink class="brand" to="/"><span class="brand-icon"><Icon name="Activity" :size="26"/></span>IRONPULSE<span class="ai-label">AI</span></RouterLink><span class="side-caption">YOUR PERSONAL PERFORMANCE LAB</span><nav><RouterLink v-for="[path,icon,title] in nav" :key="path" :to="path" :class="{active:$route.path===path}"><Icon :name="icon"/>{{title}}<span v-if="title==='AI Coach'" class="tiny-badge">LOCAL</span></RouterLink></nav><div class="sidebar-bottom"><div class="privacy-card"><Icon name="ShieldCheck"/><strong>Your progress. Your data.</strong><p>Saved on this device.<br>No fitness data sent to a server.</p></div><RouterLink class="settings-link" to="/settings"><Icon name="Settings"/> Profile & settings</RouterLink><div class="profile-mini"><span class="avatar">{{app.data.profile.name[0]?.toUpperCase()}}</span><div><strong>{{app.data.profile.name}}</strong><small>Personal workspace</small></div></div></div></aside>
<div class="main-shell"><header class="topbar"><span class="breadcrumb">MY WORKSPACE <span>/</span> {{nav.find(n=>n[0]===$route.path)?.[2]||'Settings'}}</span><span class="device-status"><span class="status-dot"></span>{{app.saving?'Saving…':'On-device workspace'}}</span><RouterLink class="avatar small" to="/settings" aria-label="Open profile">{{app.data.profile.name[0]?.toUpperCase()}}</RouterLink></header><main id="main-content" tabindex="-1"><AppUpdate/><div v-if="app.error" class="error" role="alert">{{app.error}} <button @click="app.save().catch(()=>{})">Retry save</button></div><div v-if="app.notice" class="notice" role="status">{{app.notice}}<button class="icon-button" aria-label="Dismiss" @click="app.notice=''"><Icon name="X"/></button></div><div v-if="!app.ready" class="empty">Opening your workspace…</div><RouterView v-else v-slot="{Component}"><component :is="Component"/></RouterView></main><footer>IRONPULSE AI <span>TRAIN SMARTER. GROW STRONGER.</span><RouterLink to="/settings">Visual training · 0.3.0</RouterLink></footer></div>
<nav class="bottom-nav" aria-label="Main navigation"><RouterLink v-for="[path,icon,title] in nav" :key="path" :to="path" :class="{active:$route.path===path}"><Icon :name="icon"/><span>{{title==='Overview'?'Home':title==='Training'?'Train':title}}</span></RouterLink></nav></div></template>
